1 | <!doctype html>
2 | <html lang="en">
3 | <head>
4 | <meta charset="utf-8">
5 | <meta name="viewport" content="width=device-width, initial-scale=1">
6 | <title>Blast Radius — {{FIELD_NAME}} Impact Report</title>
7 | <style>
8 |   :root {
9 |     --bg: #0b0f14;
10 |     --bg-elevated: #12181f;
11 |     --bg-card: #161d26;
12 |     --border: #232c38;
13 |     --text: #e6edf3;
14 |     --text-dim: #8b96a5;
15 |     --text-faint: #5b6472;
16 |     --accent: #4fa8ff;
17 |     --accent-dim: #1c4d7a;
18 |     --risk-high: #ff5c6c;
19 |     --risk-high-bg: #3a1a1f;
20 |     --risk-med: #f5a623;
21 |     --risk-med-bg: #3a2c14;
22 |     --risk-low: #6ee7a8;
23 |     --risk-low-bg: #123322;
24 |     --tier-field-aware: #ff5c6c;
25 |     --tier-structural: #f5a623;
26 |     --tier-dead: #6b7684;
27 |     --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
28 |     --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
29 |   }
30 |   * { box-sizing: border-box; }
31 |   body {
32 |     margin: 0;
33 |     background: var(--bg);
34 |     color: var(--text);
35 |     font-family: var(--sans);
36 |     line-height: 1.5;
37 |     padding: 0 0 80px 0;
38 |   }
39 |   .wrap { max-width: 1180px; margin: 0 auto; padding: 0 32px; }
40 | 
41 |   header.hero {
42 |     border-bottom: 1px solid var(--border);
43 |     background: linear-gradient(180deg, var(--bg-elevated) 0%, var(--bg) 100%);
44 |     padding: 48px 0 36px 0;
45 |   }
46 |   .eyebrow {
47 |     color: var(--accent);
48 |     font-size: 13px;
49 |     font-weight: 600;
50 |     letter-spacing: 0.08em;
51 |     text-transform: uppercase;
52 |     margin: 0 0 10px 0;
53 |   }
54 |   h1 {
55 |     font-size: 34px;
56 |     font-weight: 700;
57 |     margin: 0 0 6px 0;
58 |     letter-spacing: -0.01em;
59 |   }
60 |   .field-badges { margin: 14px 0 18px 0; display: flex; flex-wrap: wrap; gap: 8px; }
61 |   .badge {
62 |     display: inline-block;
63 |     font-family: var(--mono);
64 |     font-size: 13px;
65 |     padding: 4px 10px;
66 |     border-radius: 6px;
67 |     background: var(--bg-card);
68 |     border: 1px solid var(--border);
69 |     color: var(--accent);
70 |   }
71 |   .change-request {
72 |     color: var(--text-dim);
73 |     font-size: 15px;
74 |     max-width: 760px;
75 |     margin: 0 0 4px 0;
76 |   }
77 |   .meta-line {
78 |     color: var(--text-faint);
79 |     font-size: 13px;
80 |     margin-top: 14px;
81 |   }
82 | 
83 |   .stats-row {
84 |     display: grid;
85 |     grid-template-columns: repeat(5, 1fr);
86 |     gap: 14px;
87 |     margin: 32px 0 40px 0;
88 |   }
89 |   .stat-card {
90 |     background: var(--bg-card);
91 |     border: 1px solid var(--border);
92 |     border-radius: 10px;
93 |     padding: 18px 16px;
94 |   }
95 |   .stat-value { font-size: 30px; font-weight: 700; line-height: 1; }
96 |   .stat-label {
97 |     color: var(--text-dim);
98 |     font-size: 12.5px;
99 |     margin-top: 8px;
100 |     text-transform: uppercase;
101 |     letter-spacing: 0.04em;
102 |   }
103 |   .stat-card.accent-field-aware .stat-value { color: var(--tier-field-aware); }
104 |   .stat-card.accent-structural .stat-value { color: var(--tier-structural); }
105 |   .stat-card.accent-dead .stat-value { color: var(--tier-dead); }
106 |   .stat-card.accent-precision .stat-value { color: var(--risk-low); }
107 | 
108 |   section { margin: 48px 0; }
109 |   h2 {
110 |     font-size: 20px;
111 |     font-weight: 700;
112 |     margin: 0 0 4px 0;
113 |   }
114 |   .section-sub { color: var(--text-dim); font-size: 14px; margin: 0 0 20px 0; }
115 | 
116 |   table {
117 |     width: 100%;
118 |     border-collapse: collapse;
119 |     background: var(--bg-card);
120 |     border: 1px solid var(--border);
121 |     border-radius: 10px;
122 |     overflow: hidden;
123 |     font-size: 14px;
124 |   }
125 |   thead th {
126 |     text-align: left;
127 |     font-size: 12px;
128 |     text-transform: uppercase;
129 |     letter-spacing: 0.04em;
130 |     color: var(--text-dim);
131 |     background: var(--bg-elevated);
132 |     padding: 12px 14px;
133 |     border-bottom: 1px solid var(--border);
134 |   }
135 |   tbody td {
136 |     padding: 12px 14px;
137 |     border-bottom: 1px solid var(--border);
138 |     vertical-align: top;
139 |   }
140 |   tbody tr:last-child td { border-bottom: none; }
141 |   tbody tr:hover { background: var(--bg-elevated); }
142 |   td.mono, .mono-cell { font-family: var(--mono); font-size: 13px; }
143 | 
144 |   .tier-pill {
145 |     display: inline-block;
146 |     font-size: 12px;
147 |     font-weight: 600;
148 |     padding: 3px 9px;
149 |     border-radius: 999px;
150 |     white-space: nowrap;
151 |   }
152 |   .tier-pill.field-aware { background: var(--risk-high-bg); color: var(--tier-field-aware); }
153 |   .tier-pill.structural { background: var(--risk-med-bg); color: var(--tier-structural); }
154 |   .tier-pill.dead-copy { background: #1c2129; color: var(--tier-dead); }
155 | 
156 |   .risk-bar-track {
157 |     width: 90px;
158 |     height: 6px;
159 |     background: var(--bg-elevated);
160 |     border-radius: 4px;
161 |     overflow: hidden;
162 |     display: inline-block;
163 |     vertical-align: middle;
164 |     margin-right: 8px;
165 |   }
166 |   .risk-bar-fill { height: 100%; border-radius: 4px; }
167 |   .module-tag {
168 |     font-size: 11.5px;
169 |     color: var(--text-faint);
170 |     border: 1px solid var(--border);
171 |     border-radius: 5px;
172 |     padding: 1px 6px;
173 |   }
174 | 
175 |   .diagram-card {
176 |     background: var(--bg-card);
177 |     border: 1px solid var(--border);
178 |     border-radius: 10px;
179 |     padding: 24px;
180 |     overflow-x: auto;
181 |   }
182 | 
183 |   .precision-note {
184 |     background: var(--bg-card);
185 |     border: 1px solid var(--border);
186 |     border-left: 3px solid var(--risk-low);
187 |     border-radius: 8px;
188 |     padding: 16px 18px;
189 |     font-size: 14px;
190 |     color: var(--text-dim);
191 |     margin-bottom: 20px;
192 |   }
193 |   .precision-note b { color: var(--text); }
194 | 
195 |   footer {
196 |     margin-top: 64px;
197 |     padding-top: 24px;
198 |     border-top: 1px solid var(--border);
199 |     color: var(--text-faint);
200 |     font-size: 12.5px;
201 |   }
202 | 
203 |   @media (max-width: 900px) {
204 |     .stats-row { grid-template-columns: repeat(2, 1fr); }
205 |   }
206 | </style>
207 | </head>
208 | <body>
209 | 
210 | <header class="hero">
211 |   <div class="wrap">
212 |     <p class="eyebrow">Blast Radius · Change Impact Report</p>
213 |     <h1>{{FIELD_NAME}}</h1>
214 |     <div class="field-badges">
215 |       {{FIELD_ALIAS_BADGES}}
216 |     </div>
217 |     <p class="change-request">&ldquo;{{CHANGE_REQUEST_TEXT}}&rdquo;</p>
218 |     <p class="meta-line">Generated {{GENERATED_AT}} &middot; {{SCOPE_SUMMARY}}</p>
219 |   </div>
220 | </header>
221 | 
222 | <div class="wrap">
223 | 
224 |   <div class="stats-row">
225 |     <div class="stat-card accent-field-aware">
226 |       <div class="stat-value">{{STAT_FIELD_AWARE}}</div>
227 |       <div class="stat-label">Field-aware programs</div>
228 |     </div>
229 |     <div class="stat-card accent-structural">
230 |       <div class="stat-value">{{STAT_STRUCTURAL}}</div>
231 |       <div class="stat-label">Structurally affected</div>
232 |     </div>
233 |     <div class="stat-card accent-dead">
234 |       <div class="stat-value">{{STAT_DEAD_COPY}}</div>
235 |       <div class="stat-label">Dead copies found</div>
236 |     </div>
237 |     <div class="stat-card">
238 |       <div class="stat-value">{{STAT_TOTAL_AFFECTED}}</div>
239 |       <div class="stat-label">Total affected programs</div>
240 |     </div>
241 |     <div class="stat-card accent-precision">
242 |       <div class="stat-value">{{STAT_REJECTED_NEAR_MISSES}}</div>
243 |       <div class="stat-label">Near misses rejected</div>
244 |     </div>
245 |   </div>
246 | 
247 |   <section>
248 |     <h2>Affected programs, ranked by risk</h2>
249 |     <p class="section-sub">Risk score combines tier, the kinds of access found (a WRITE ranks above a DISPLAY), and whether the program is part of the core application or an optional integration module. See methodology below for the exact formula.</p>
250 |     <table>
251 |       <thead>
252 |         <tr>
253 |           <th>#</th>
254 |           <th>Program</th>
255 |           <th>Module</th>
256 |           <th>Tier</th>
257 |           <th>Risk</th>
258 |           <th>Access kinds</th>
259 |           <th>Notes</th>
260 |         </tr>
261 |       </thead>
262 |       <tbody>
263 |         {{PROGRAM_TABLE_ROWS}}
264 |       </tbody>
265 |     </table>
266 |   </section>
267 | 
268 |   <section>
269 |     <h2>Dependency graph</h2>
270 |     <p class="section-sub">{{FIELD_NAME}} and its aliases, and every program that touches them, colored by tier.</p>
271 |     <div class="diagram-card">
272 |       <pre class="mermaid">
273 | {{MERMAID_DIAGRAM}}
274 |       </pre>
275 |     </div>
276 |   </section>
277 | 
278 |   <section>
279 |     <h2>Precision: near misses correctly rejected</h2>
280 |     <p class="section-sub">Every one of these looked like a hit to a plain text search — each contains the field name or an alias as a substring — and was independently confirmed to be a different, separately-declared identifier.</p>
281 |     <div class="precision-note">
282 |       <b>{{STAT_REJECTED_NEAR_MISSES}} near misses</b> were found and excluded across {{STAT_NEAR_MISS_PROGRAM_COUNT}} programs. Rejection reasons: {{REJECTION_REASON_BREAKDOWN}}.
283 |     </div>
284 |     <table>
285 |       <thead>
286 |         <tr>
287 |           <th>Identifier found</th>
288 |           <th>Program</th>
289 |           <th>Line</th>
290 |           <th>Why it was rejected</th>
291 |         </tr>
292 |       </thead>
293 |       <tbody>
294 |         {{NEAR_MISS_TABLE_ROWS}}
295 |       </tbody>
296 |     </table>
297 |   </section>
298 | 
299 |   <section>
300 |     <h2>Methodology</h2>
301 |     <p class="section-sub">
302 |       Five-stage pipeline run inside IBM Bob: INVENTORY walked the full
303 |       CardDemo application; SPEC resolved the plain-language change request
304 |       above to {{FIELD_NAME}} and its aliases against the actual copybook
305 |       declarations; TRACE dispatched parallel subagents, each scanning a
306 |       small group of candidate programs and actively chasing MOVE/
307 |       REDEFINES/record-level READ INTO chains to discover further,
308 |       locally-declared aliases beyond the copybook-declared ones SPEC
309 |       found; VERIFY independently re-checked every claimed hit and every
310 |       newly-discovered alias against the source, respecting COBOL column-7
311 |       comment rules and string-literal spans, accepting a same-shaped
312 |       identifier as a real alias when it is genuinely fed by the target's
313 |       value and rejecting it only when it is a different entity or dead,
314 |       unfed code; SYNTHESIS produced this report from only the hits that
315 |       survived verification.
316 |       Risk score = (tier base + sum of access-kind weights) &times; module
317 |       multiplier (core = 1.0, optional-integration = 0.7).
318 |     </p>
319 |   </section>
320 | 
321 |   <footer>
322 |     Blast Radius &middot; generated by an IBM Bob IDE pipeline (Skill: blast-radius) &middot; {{GENERATED_AT}}
323 |   </footer>
324 | 
325 | </div>
326 | 
327 | <script type="module">
328 |   import mermaid from "https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.esm.min.mjs";
329 |   mermaid.initialize({ startOnLoad: true, theme: "dark" });
330 | </script>
331 | </body>
332 | </html>
